insert into settings.step_profiles (id, key, name, description, is_default) values (md5('step-profile:short')::uuid, 'short', 'Short', 'Plan, build with tests, continuous integration, independent check. About half the time and cost of the 16 steps in the build spike (3.6 against 7.9 minutes).', true) on conflict (key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:short:plan')::uuid, md5('step-profile:short')::uuid, 1, 'plan', 'Plan', false, 0.8, $p$Step PLAN. Read CONTRACT.md and the code of the template. Write docs/PLAN.md: the acceptance criteria of the task "{task}" (numbered, each verifiable), the API (endpoints, request and response), the database tables (a migration with the next free version number), the backend classes, the frontend components, and the list of tests that prove each criterion. Keep it under 80 lines. Do not write production code or tests in this step.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:short:build')::uuid, md5('step-profile:short')::uuid, 2, 'build', 'Build with tests', true, 3.5, $p$Step BUILD WITH TESTS. Implement docs/PLAN.md completely: migration, backend, frontend and the tests that prove every criterion (backend tests against the real PostgreSQL, frontend logic tests with Vitest). Run ./check.sh and fix until it prints CHECK PASSED.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:short:ci')::uuid, md5('step-profile:short')::uuid, 3, 'ci', 'Continuous integration', true, 1.5, $p$Step CONTINUOUS INTEGRATION. Run ./check.sh from the workspace root as the pipeline would. If it fails, find the cause and fix it without weakening any test. Check there are no compiler or type warnings in the output and fix them. End when it prints CHECK PASSED.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:short:check')::uuid, md5('step-profile:short')::uuid, 4, 'check', 'Independent check', true, 2.0, $p$Step INDEPENDENT CHECK. You did not write this code. Review the workspace against the acceptance criteria in docs/PLAN.md and CONTRACT.md: is every criterion implemented, is each one proven by a test that would fail if the behaviour were broken, does the application behave as the contract says? Write docs/CHECK.md with a verdict per criterion (pass or fail, with evidence) and an overall verdict. Fix real defects you find (code or tests) and run ./check.sh until it prints CHECK PASSED.$p$) on conflict (profile_id, key) do nothing;
insert into settings.step_profiles (id, key, name, description, is_default) values (md5('step-profile:full')::uuid, 'full', '16 steps', 'The 16 steps of the development workflow, one builder invocation each with the role named: more documents and an audit trail, about twice the time and cost.', false) on conflict (key) do update set description = excluded.description;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:01-define')::uuid, md5('step-profile:full')::uuid, 1, '01-define', 'Define', false, 0.4, $p$Step 1 DEFINE (role Product Owner and Business Analyst). Read CONTRACT.md. Write docs/01-STORY.md: the user story of the task "{task}" with the "so that" clause, numbered acceptance criteria as Given/When/Then scenarios (the happy path and the errors of the task), and what is out of scope. Under 60 lines. No code.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:02-plan')::uuid, md5('step-profile:full')::uuid, 2, '02-plan', 'Plan', false, 0.4, $p$Step 2 PLAN (role Lead Developer). Read docs/01-STORY.md and the template. Write docs/02-PLAN.md: task specs per area (database, API, backend, frontend, tests) and the order of work. Under 50 lines. No code.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:03-design')::uuid, md5('step-profile:full')::uuid, 3, '03-design', 'Design', false, 0.4, $p$Step 3 DESIGN (role UX/UI Designer). Write docs/03-DESIGN.md: the screen flow (the steps the user goes through for the task), states (loading, empty, error), component list and the text of every label. Under 50 lines. No code.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:04-contract')::uuid, md5('step-profile:full')::uuid, 4, '04-contract', 'Contract', false, 0.4, $p$Step 4 CONTRACT (role API Contract Owner). Write api/openapi.yaml (OpenAPI 3.1) with the endpoints for the story: the endpoints the task needs, with problem+json errors. Keep it minimal and consistent with docs/02-PLAN.md. No code.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:05-data')::uuid, md5('step-profile:full')::uuid, 5, '05-data', 'Data', false, 0.5, $p$Step 5 DATA (role Database Engineer). Add a Flyway migration in backend/src/main/resources/db/migration/ with the next free version number for the tables the task needs (forward-only, indexes on foreign keys, a few seed rows if the task needs them). Do not write Java.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:06-build')::uuid, md5('step-profile:full')::uuid, 6, '06-build', 'Build', true, 3.0, $p$Step 6 BUILD (roles Backend and Frontend Developer). Implement the story following api/openapi.yaml, the migration and docs/03-DESIGN.md: backend endpoints and the frontend screens. Keep ./check.sh green. Write the minimum of tests needed to compile; the Tester completes them in the next step.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:07-environment')::uuid, md5('step-profile:full')::uuid, 7, '07-environment', 'Environment', false, 0.3, $p$Step 7 ENVIRONMENT (role DevOps Engineer). Check that ./check.sh and the application start (cd backend && ./gradlew bootRun is not needed; just review the build files and application.yaml). Change them only if the story needs it, otherwise write docs/07-ENV.md with one line saying nothing was needed.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:08-test')::uuid, md5('step-profile:full')::uuid, 8, '08-test', 'Test', true, 2.0, $p$Step 8 TEST (role Tester). Write the tests that prove every acceptance criterion of docs/01-STORY.md: backend tests on the real PostgreSQL and frontend logic tests with Vitest. Map each criterion to its test in docs/08-TESTMAP.md. Run ./check.sh until CHECK PASSED.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:09-verification')::uuid, md5('step-profile:full')::uuid, 9, '09-verification', 'Team verification', false, 1.0, $p$Step 9 TEAM VERIFICATION (roles Product Owner, Architect, Backend, Frontend, Tester, DevOps). Review the workspace once per role and write docs/09-VERDICTS.md with one verdict (approve or findings) per role with evidence. Do not change code in this step.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:10-pipeline')::uuid, md5('step-profile:full')::uuid, 10, '10-pipeline', 'Pipeline', true, 1.0, $p$Step 10 PIPELINE (role DevOps Engineer). Run ./check.sh from the workspace root as the pipeline. If it fails, fix the cause without weakening any test; fix all warnings. End on CHECK PASSED.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:11-review')::uuid, md5('step-profile:full')::uuid, 11, '11-review', 'Review', false, 1.0, $p$Step 11 REVIEW (role Reviewer). Review the whole change against the project rules in the builder guide (CLAUDE.md or GEMINI.md, same content) (complexity, naming, no secrets, tests meaningful). Write docs/11-REVIEW.md listing findings with severity. Do not change code.$p$) on conflict (profile_id, key) do update set prompt = excluded.prompt;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:12-fix')::uuid, md5('step-profile:full')::uuid, 12, '12-fix', 'Fix', true, 1.5, $p$Step 12 FIX AND VERIFY (roles authors and Debug Engineer). Fix every finding of docs/09-VERDICTS.md and docs/11-REVIEW.md with severity high or medium, and note in docs/12-FIXES.md what was fixed. Run ./check.sh until CHECK PASSED.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:13-accept')::uuid, md5('step-profile:full')::uuid, 13, '13-accept', 'Accept', true, 1.0, $p$Step 13 ACCEPT (role Product Owner). Start the application (cd backend && ./gradlew bootRun in the background on port 18080 with the APP_DB_URL from the environment), call the API with curl for the happy path and one error, stop the application, and write docs/13-ACCEPT.md with the result per acceptance criterion. Fix defects you find and finish on ./check.sh passing.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:14-document')::uuid, md5('step-profile:full')::uuid, 14, '14-document', 'Document', false, 0.4, $p$Step 14 DOCUMENT (role Technical Writer). Write README.md: what the application does, how to build and run it, the endpoints of the story. Under 40 lines.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:15-merge')::uuid, md5('step-profile:full')::uuid, 15, '15-merge', 'Merge', true, 0.4, $p$Step 15 MERGE AND DEPLOY (role Lead Developer). Confirm the workspace is complete and clean (no stray files, no secrets, .gitignore covers build output), then run ./check.sh once more and write docs/15-MERGE.md with one line per check. Do not run git commands that change history.$p$) on conflict (profile_id, key) do nothing;
insert into settings.profile_steps (id, profile_id, seq, key, title, gated, cap_usd, prompt) values (md5('step:full:16-audit')::uuid, md5('step-profile:full')::uuid, 16, '16-audit', 'Audit', true, 1.5, $p$Step 16 AUDIT AND VERIFY (role Auditor). Check the evidence of all earlier steps: every acceptance criterion has a verdict and a test, the last ./check.sh run is green, nothing in the docs contradicts the code. Write docs/16-AUDIT.md with the final verdict (DONE or NOT DONE) and the reason.$p$) on conflict (profile_id, key) do nothing;
